}

#hp-lightbox .hp-lb-nav {
  flex: none;
  width: 32px;
  height: 32px;
}

#hp-lightbox .hp-lb-nav:disabled {
  opacity: 0.3;
  cursor: default;
}

#hp-lightbox .hp-lb-close {
  position: absolute;
  top: 16px;
  right: 16px;
  width: 32px;
  height: 32px;
}

#hp-lightbox .hp-lb-del {
