#hp-gate {
  position: fixed;
  z-index: 100000;
  top: 0;
  left: 0;
  width: 100vw;
  height: 100vh;
  height: 100dvh;
  display: grid;
  place-items: center;
  background:
    linear-gradient(var(--hp-wash), var(--hp-wash)),
