      const c = pick.chars[+v]; chosenAvatar = c.avatar; nameIn.value = c.name; msg.focus();
    });
    // 一页三条，新的在前：签到的多了，左栏也不会越拉越长
    function render() {
      const list = gbLoad();
      const pages = Math.max(1, Math.ceil(list.length / GB_PAGE));
      page = Math.min(page, pages - 1);
