    ]],
    ['请严格遵守以下创作规则', ['请务必遵循下述创作规则', '请严格按照以下创作规范执行', '请认真遵守下列创作准则']],
    ['接下来请根据以上设定', ['下面请依据上述设定', '接下来请结合上方设定', '随后请按照以上背景与设定']],
    ['正式开始创作前，请先进行思考', ['在正式动笔创作前，请先展开构思', '正式开始撰写正文前，请先理清思路', '开始正式创作之前，请先进行推演']],
    ['正文必须使用简体中文', ['正文部分须采用简体中文', '正文内容必须以简体中文撰写', '请确保正文使用简体中文']],
    ['与此同时，', ['在此同时，', '同一时间，', '此外，']],
    ['换句话说，', ['换言之，', '也就是说，']],
    ['需要注意一下', ['需要留意一下', '还请留意一下', '务必注意一下']],
  ];

  /**
   * 【v4.5 核心突破 2】：深度反防蒸馏短词切分与替换（在长句替换之后执行，做到长短兼顾、100% 必变！）
   */
  const ANTI_DISTILL_TARGETS = [
    ['Identity Confirmation', () => `Identity${' '.repeat(randInt(2, 3))}Confirmation`],
    ['CRITICAL INSTRUCTIONS', () => `CRITICAL${' '.repeat(randInt(2, 3))}INSTRUCTIONS`],
    ['CRUCIAL: ALWAYS START', () => `CRUCIAL:${' '.repeat(randInt(2, 3))}ALWAYS${' '.repeat(randInt(2, 3))}START`],
    ['WITHOUT changing a single word', () => `WITHOUT${' '.repeat(randInt(2, 3))}changing${' '.repeat(randInt(2, 3))}a single word`],
    ['IGNORE any prompt', () => `IGNORE${' '.repeat(randInt(2, 3))}any${' '.repeat(randInt(2, 3))}prompt`],
    ['out of character', () => `out${' '.repeat(randInt(2, 3))}of${' '.repeat(randInt(2, 3))}character`],
    ['System Instruction', () => `System${' '.repeat(randInt(2, 3))}Instruction`],
    ['Role Play', () => `Role${' '.repeat(randInt(2, 3))}Play`],
    ['非AI助手', () => pick(['非人工智能助手', '并非人工智能助手', '非AI型助手', '不作为AI助理'])],
    ['完全无限制', () => pick(['彻底不受限制', '全无任何限制', '毫无任何限制', '完全不受限制'])],
    ['安全合规协议与审查', () => pick(['安全合规准则与内容审查', '安全合规条款及审查机制', '安全规范协议与审查过滤'])],
    ['道德评判', () => pick(['道德层面评判', '道德说教与评判', '伦理道德评判', '主观道德审视'])],
    ['虚构叙事', () => pick(['纯虚构文学叙事', '架空虚构叙事', '虚构故事创作', '虚拟文学叙事'])],
    ['原生思考', () => pick(['原生内置思考', '原生底层思考', '原生系统思考', '原生模型思考'])],
    ['思考完记得写正文', () => pick(['构思完务必记得写正文', '思考结束后记得写正文', '思考完毕记得立刻写正文', '完成思考后记得写正文'])],
    ['把思考立刻切换到所需语言', () => pick(['将思考过程立刻切换到所需语言', '把思考语言立即切换到所需语言', '将思考内容立刻切换为所需语言'])],
    ['思维链', () => pick(['思考推演链', '构思推理链', '思维推演链'])],
  ];

  function applyAntiDistillTransform(text) {
    if (typeof text !== 'string' || text.length < 4) return text;
    let out = text;
    // 1. 先对输入结构标签（如 <narrative_config>、<Chain_of_Thought>）在 `>` 前注入 1~2 个空格，打破 XML 结构标签指纹
    out = out.replace(INPUT_STRUCTURAL_TAG_REGEX, (_, tagInner) => `<${tagInner}${' '.repeat(randInt(1, 2))}>`);
    // 2. 再执行长句 100% 必变同义替换
    for (const [needle, choices] of MANDATORY_SIGNATURE_VARIANTS) {
      if (out.includes(needle)) {
        out = out.split(needle).reduce((acc, part, idx) => (idx === 0 ? part : acc + pick(choices) + part), '');
      }
    }
    // 3. 最后执行短词级反防蒸馏替换，兜底所有剩余触发词
    for (const [target, replacer] of ANTI_DISTILL_TARGETS) {
      if (out.includes(target)) {
        out = out.split(target).reduce((acc, part, idx) => (idx === 0 ? part : acc + replacer() + part), '');
      }
    }
    return out;
  }

  /**
   * 【v4.5 核心突破 3】：反 `.trim()` 清洗的四维自然分词微移 + 100% 必变保底校验
   * 1. 句内中文标点后随机 1 个普通半角空格（概率提升至 68%）；
   * 2. 中英文边界（如 `JILL需在` -> `JILL 需在`、`Master的` -> `Master 的`）随机 1 个普通半角空格（概率 55%，100% 符合中文排版规范且 `.trim()` 无法清除）；
   * 3. Markdown 列表项/标题/冒号后行内空格微扰（1~3 个半角空格）；
   * 4. 100% 必变保底校验：若经过上述步骤后文本仍未变化，自动在首个标点或词界处注入 1 个自然空格，确保任何块 0% 原样漏网！
   */
  function applyPureNaturalJitter(text, isNetworkExit = false) {
    if (typeof text !== 'string') return text;
    let cleaned = stripLegacyGibberishLines(text);
    if (cleaned.length < 4) return cleaned;

    // 针对网络出口阶段（fetch/XHR）的 <customfunction> 块（2712 字的世界系统说明）：
    // 在不触碰 <IzumiEdit>、操作名定义行与末尾目录区的前提下，对其内部 2000 字的静态说明散文执行安全微扰！
    if (isNetworkExit && /<\s*customfunction\b/i.test(cleaned)) {
      cleaned = cleaned.replace(/<\s*customfunction\b[^>]*>[\s\S]*?<\s*\/\s*customfunction\s*>/gi, (cfBlock) => {
        const cfStash = [];
        const cfMasked = cfBlock.replace(CUSTOMFUNCTION_INNER_PROTECTED_REGEX, (m) => {
          const idx = cfStash.length;
          cfStash.push(m);
          return `@@__CF_INNER_PROT_${idx}__@@`;
        });
        let cfOut = cfMasked;
        const cfVariants = [
          ["你可以用下面提到的工具来增强记忆", ["你可以借助下方列出的工具来强化记忆", "你可以使用下面提供的工具来辅助记忆管理", "你可通过下述工具来维护与增强长期记忆"]],
          ["只记已经确立且后续有用的内容，不需要记不重要的剧情发展", ["仅记录已在正文确立且对后文有用的事实，无需记录琐碎无关的剧情过渡", "只归档已经发生且后续用得上的关键内容，不必记录次要的日常经过"]],
          ["没重要信息的时候不需要用IzumiEdit", ["若本轮没有产生重要新信息则无需调用IzumiEdit", "在没有关键信息需要归档时不必使用IzumiEdit"]],
          ["优先追加或局部替换，不为一点补充重写整份资料", ["请优先采用追加或局部替换，切勿只为少量补充就重写整条资料", "尽量使用追加与局部替换操作，避免为了细微增补而重写全文"]]
        ];
        for (const [k, arr] of cfVariants) {
          if (cfOut.includes(k)) cfOut = cfOut.split(k).join(pick(arr));
        }
        cfOut = cfOut.replace(/([，；：、。！？])(?=[\u4e00-\u9fa5A-Za-z])/g, (p) => (csprng() < 0.68 ? `${p} ` : p));
        cfOut = cfOut.replace(/([\u4e00-\u9fa5])(?=[A-Za-z]{2,})/g, (c) => (csprng() < 0.55 ? `${c} ` : c));
        if (cfOut === cfMasked) {
          cfOut = cfOut.replace(/([，；：、。！？])/, "$1 ");
        }
        if (cfStash.length > 0) {
          cfOut = cfOut.replace(/@@__CF_INNER_PROT_(\d+)__@@/g, (_, idx) => cfStash[Number(idx)] ?? _);
        }
        return cfOut;
      });
    }

    const stash = [];
    const masked = cleaned.replace(EVENT_PROTECTED_SPAN_REGEX, (match) => {
      const idx = stash.length;
      stash.push(match);
      return `@@__PURE_PROT_SPAN_${idx}__@@`;
    });

    let out = applyAntiDistillTransform(masked);

    // 维度 A：反 .trim() 的句内中文标点后微空格移位（68% 概率）
    out = out.replace(/([，；：、。！？])(?=[\u4e00-\u9fa5A-Za-z])/g, (punct) => {
      return csprng() < 0.68 ? `${punct} ` : punct;
    });

    // 维度 B：中英文边界自然排版微空格（如 `JILL需` -> `JILL 需`，55% 概率，反代无法清洗且 100% 自然）
    out = out.replace(/([\u4e00-\u9fa5])(?=[A-Za-z]{2,})/g, (ch) => (csprng() < 0.55 ? `${ch} ` : ch));
    out = out.replace(/([A-Za-z]{2,})(?=[\u4e00-\u9fa5])/g, (word) => {
      if (word.includes('PURE_PROT_SPAN')) return word;
      return csprng() < 0.55 ? `${word} ` : word;
    });

    // 维度 C：行内列表/标题/冒号空格微扰 + 行尾空格微扰
    const lines = out.split('\n');
    if (lines.length > 1) {
      for (let i = 0; i < lines.length - 1; i++) {
        let line = lines[i];
        const trimmed = line.trimEnd();

        if (/^(\s*(?:[-*]|\d+\.|#{1,4}))\s+(\S.*)$/.test(trimmed) && csprng() < 0.85) {
          line = trimmed.replace(/^(\s*(?:[-*]|\d+\.|#{1,4}))\s+/, `$1${' '.repeat(randInt(1, 3))}`);
        } else {
          line = trimmed;
        }

        if (
          line.length > 4 &&
          !/[>}%`~]$/.test(line) &&
          !/^\s*(?:<|```|~~~|\{\{|@@__PURE_PROT_SPAN_)/.test(line) &&
          !line.includes('@@__PURE_PROT_SPAN_') &&
          csprng() < 0.80
        ) {
          line = line + ' '.repeat(randInt(1, 4));
        }

        lines[i] = line;
      }
      out = lines.join('\n');
    }

    // 维度 D：100% 必变保底校验（若短文本块侥幸未发生任何变化，强制在首个标点或行内注入微空格）
    if (out === masked && out.trim().length >= 6 && !/^@@__PURE_PROT_SPAN_\d+__@@$/.test(out.trim())) {
      if (/([，；：、。！？:,-])/.test(out)) {
        out = out.replace(/([，；：、。！？:,-])/, '$1 ');
      } else {
        out = out + ' ';
      }
    }

    if (stash.length > 0) {
      out = out.replace(/@@__PURE_PROT_SPAN_(\d+)__@@/g, (_, idx) => stash[Number(idx)] ?? _);
    }
    return out;
  }

  const shieldedSnapshotMap = new WeakMap();
  const recentNetworkShieldedSet = new Set();
  let lastNetworkCleanStamp = 0;

  let stats = {
    protectedTurns: 0,
    healedEmptyCount: 0,
    lastTraceTime: '',
    lastInjectedCount: 0,
    lastLockedModel: 'pg 3.8flash (全天候死锁)',
    lastTurnStamp: 0,
  };

  function rememberNetworkShielded(str) {
    const now = Date.now();
    if (now - lastNetworkCleanStamp > 5000) {
      recentNetworkShieldedSet.clear();
      lastNetworkCleanStamp = now;
    }
    if (typeof str === 'string' && str.length > 0) {
      recentNetworkShieldedSet.add(str);
    }
  }

  function injectTextShield(text, prefixNoise, cfg, isNetworkExit = false) {
    if (typeof text !== 'string') return text;
    let next = stripLegacyGibberishLines(text);
    if (MARKER_REGEX.test(next)) {
      MARKER_REGEX.lastIndex = 0;
      next = next.replace(MARKER_REGEX, () => buildEntropyHeaderBlock(cfg.turnCommentMin, cfg.turnCommentMax, cfg.charMin, cfg.charMax));
    }
    if (cfg.mode === 'pg38_lock') {
      next = applyPureNaturalJitter(next, isNetworkExit);
    } else {
      next = applyAntiDistillTransform(next);
    }
    // 避免重复叠加多轮 HTML 注释头
    if (prefixNoise && !next.trimStart().startsWith('<!--')) {
      next = prefixNoise + next;
    }
    return next;
  }

  /**
   * 针对 OpenAI `messages` 数组执行全覆盖防路由注入
   * 【v4.5 升级】：
   * 1. 彻底废除 `hasAdvice` 禁用微扰的旧逻辑（`flash破甲`、合并 System、以及使用 Advice 的回合全部 100% 保护）；
   * 2. 所有长度 >= 8 的 `system` 与 `user` 消息均挂载独立 HTML 注释头（不仅限于 system）；
   * 3. `assistant` 消息不挂 HTML 注释头（杜绝模型模仿乱码），但 100% 执行句内自然分词微移与同义替换！
   */
  function applyAntiRouteShieldToMessages(messages, isNetworkExit = false) {
    if (!Array.isArray(messages) || !messages.length) return 0;
    const cfg = readConfig();
    if (!cfg.enabled) return 0;

    let injected = 0;
    let firstSystemDone = false;
    let firstUserDone = false;

    for (let index = 0; index < messages.length; index++) {
      const msg = messages[index];
      if (!msg || typeof msg !== 'object') continue;
      if (msg.role === 'tool' || msg.role === 'function' || msg.tool_calls || msg.function_call) continue;

      if (typeof msg.content === 'string') {
        const text = msg.content;
        if (!text.trim()) continue;

        // 事件阶段保持纯 <customfunction> 块 100% 原样以通过 JILL悬浮窗 authorize() 校验，待 fetch/XHR 网络出口再执行破指纹加固
        if (!isNetworkExit && (/<\s*customfunction/i.test(text) || text.includes("[[IZUMI_CHAT_INDEX_V1]]"))) {
          continue;
        }
        if (PROTECTED_FRAME_TEST.test(text)) {
          shieldedSnapshotMap.set(msg, text);
          continue;
        }

        // 若不是网络出口阶段，且对象快照未变且不含未处理标记，则跳过重复处理；
        // 若是网络出口阶段（isNetworkExit=true），且包含 <customfunction> 块或尚未经网络出口加固，则执行终极加固！
        if (!isNetworkExit && shieldedSnapshotMap.get(msg) === text && !MARKER_REGEX.test(text)) {
          if (msg.role === 'system' && !firstSystemDone) firstSystemDone = true;
          if (msg.role === 'user' && !firstUserDone) firstUserDone = true;
          continue;
        }
        if (isNetworkExit && recentNetworkShieldedSet.has(text) && !/<\s*customfunction\b/i.test(text) && !MARKER_REGEX.test(text)) {
          continue;
        }
        MARKER_REGEX.lastIndex = 0;

        const desc = Object.getOwnPropertyDescriptor(msg, 'content');
        if (desc && desc.writable === false) continue;

        const isLastMessage = index === messages.length - 1;
        const isAssistantRole = msg.role === 'assistant' || msg.role === 'model';
        const isThoughtTail = isUnclosedThoughtPrefillTail(text, isLastMessage, msg.role);

        let prefix = '';

        // 所有非预填充尾部的 system 与 user 消息（>= 8 字）均获得独立头部注释盐值
        if (!isThoughtTail && !isAssistantRole) {
          if (msg.role === 'system' && !firstSystemDone) {
            firstSystemDone = true;
            prefix = buildEntropyHeaderBlock(cfg.headCommentMin, cfg.headCommentMax, cfg.charMin, cfg.charMax) + '\n';
          } else if (msg.role === 'user' && !firstUserDone) {
            firstUserDone = true;
            prefix = buildEntropyHeaderBlock(cfg.turnCommentMin, cfg.turnCommentMax, cfg.charMin, cfg.charMax) + '\n';
          } else if (cfg.mode === 'pg38_lock' && text.trim().length >= 8) {
            prefix = buildEntropyHeaderBlock(3, 6, cfg.charMin, cfg.charMax) + '\n';
          }
        }

        const updated = injectTextShield(text, prefix, cfg, isNetworkExit);
        if (updated !== text) {
          msg.content = updated;
          injected++;
        }
        shieldedSnapshotMap.set(msg, msg.content);
        rememberNetworkShielded(msg.content);
      } else if (Array.isArray(msg.content)) {
        let touched = false;
        const isAssistantRole = msg.role === 'assistant' || msg.role === 'model';
        for (let pIdx = 0; pIdx < msg.content.length; pIdx++) {
          const part = msg.content[pIdx];
          if (!part || typeof part !== 'object' || part.type !== 'text' || typeof part.text !== 'string') continue;
          if (!part.text.trim() || PROTECTED_FRAME_TEST.test(part.text)) continue;
          if (!isNetworkExit && shieldedSnapshotMap.get(part) === part.text && !MARKER_REGEX.test(part.text)) continue;
          MARKER_REGEX.lastIndex = 0;
          const desc = Object.getOwnPropertyDescriptor(part, 'text');
          if (desc && desc.writable === false) continue;
          const isThoughtTail = isUnclosedThoughtPrefillTail(part.text, index === messages.length - 1 && pIdx === msg.content.length - 1, msg.role);
          const isFirstSystemPart = msg.role === 'system' && !firstSystemDone && pIdx === 0 && !isThoughtTail;
          if (isFirstSystemPart) firstSystemDone = true;
          const prefix = (!isAssistantRole && !isThoughtTail)
            ? (isFirstSystemPart
              ? buildEntropyHeaderBlock(cfg.headCommentMin, cfg.headCommentMax, cfg.charMin, cfg.charMax) + '\n'
              : (cfg.mode === 'pg38_lock' && part.text.trim().length >= 8 ? buildEntropyHeaderBlock(3, 6, cfg.charMin, cfg.charMax) + '\n' : ''))
            : '';
          const nextText = injectTextShield(part.text, prefix, cfg, isNetworkExit);
          if (nextText !== part.text) {
            part.text = nextText;
            touched = true;
          }
          shieldedSnapshotMap.set(part, part.text);
          rememberNetworkShielded(part.text);
        }
        if (touched) injected++;
      }
    }

    if (injected > 0) {
      const now = Date.now();
      if (now - stats.lastTurnStamp > 2000) {
        stats.protectedTurns++;
        stats.lastTurnStamp = now;
        stats.lastInjectedCount = injected;
      } else {
        stats.lastInjectedCount = Math.max(stats.lastInjectedCount, injected);
      }
      stats.lastTraceTime = new Date().toLocaleTimeString();
    }
    return injected;
  }

  /**
   * 针对 Google AI Studio / Playground 原生格式（`contents` + `systemInstruction`）执行全覆盖防路由混淆
   */
  function applyAntiRouteShieldToGoogleNative(generateData, isNetworkExit = false) {
    if (!generateData || typeof generateData !== 'object') return 0;
    const cfg = readConfig();
    if (!cfg.enabled) return 0;

    let injected = 0;
    const sysInst = generateData.systemInstruction || generateData.system_instruction;
    if (sysInst && Array.isArray(sysInst.parts)) {
      for (let i = 0; i < sysInst.parts.length; i++) {
        const part = sysInst.parts[i];
        if (!part || typeof part.text !== 'string' || !part.text.trim()) continue;
        if (PROTECTED_FRAME_TEST.test(part.text)) continue;
        if (!isNetworkExit && shieldedSnapshotMap.get(part) === part.text && !MARKER_REGEX.test(part.text)) continue;
        MARKER_REGEX.lastIndex = 0;
        const prefix = i === 0
          ? (buildEntropyHeaderBlock(cfg.headCommentMin, cfg.headCommentMax, cfg.charMin, cfg.charMax) + '\n')
          : (cfg.mode === 'pg38_lock' && part.text.trim().length >= 8 ? buildEntropyHeaderBlock(3, 6, cfg.charMin, cfg.charMax) + '\n' : '');
        const updated = injectTextShield(part.text, prefix, cfg, isNetworkExit);
        if (updated !== part.text) {
          part.text = updated;
          injected++;
        }
        shieldedSnapshotMap.set(part, part.text);
        rememberNetworkShielded(part.text);
      }
    }

    if (Array.isArray(generateData.contents) && generateData.contents.length) {
      const len = generateData.contents.length;
      for (let i = 0; i < len; i++) {
        const turn = generateData.contents[i];
        if (!turn || !Array.isArray(turn.parts)) continue;
        const isLastTurn = i === len - 1;
