            // 2. 获取页面上所有的塔罗状态栏 (确保聊天记录中的历史状态栏也能同步)
            const wrappers = document.querySelectorAll('.tarot-wrapper');

            wrappers.forEach(wrapper => {
                // 3. 初始化应用缓存的主题
                if (savedTheme === 'light') {
                    wrapper.classList.add('theme-light');
                } else {
                    wrapper.classList.remove('theme-light');
                }

                // 4. 为切换按钮绑定点击事件
                const toggleBtn = wrapper.querySelector('.tarot-toggle');
                // 使用 dataset.bound 防止在多次渲染时重复绑定事件
                if (toggleBtn && !toggleBtn.dataset.bound) {
                    toggleBtn.dataset.bound = "true";

                    toggleBtn.addEventListener('click', function() {
                        const isCurrentlyLight = wrapper.classList.contains('theme-light');
                        const newTheme = isCurrentlyLight ? 'dark' : 'light';

                        // 更新缓存
                        localStorage.setItem('tarotTheme', newTheme);

                        // 同步更新页面上所有的状态栏，保持聊天记录里的样式统一
                        const allWrappers = document.querySelectorAll('.tarot-wrapper');
                        allWrappers.forEach(w => {
                            if (newTheme === 'light') {
                                w.classList.add('theme-light');
                            } else {
                                w.classList.remove('theme-light');
                            }
                        });
                    });
                }
            });
        })();
    </script>
</body>
</html>
