    <div class="scroll-mount is-collapsed" id="main-container">
        <!-- 竹叶 -->
        <div id="bamboo-layer"></div>

        <!-- 头部 -->
        <div class="header-section" id="header-trigger">
            <h1 class="main-title">浮生绘卷</h1>
        </div>

        <div class="collapsible-wrapper">
