<script>
document.addEventListener('DOMContentLoaded', function() {
    const cardContainer = document.getElementById('ryx-card');
    const themeAutoBtn = document.getElementById('btn-auto');
    const themeLightBtn = document.getElementById('btn-light');
    const themeDarkBtn = document.getElementById('btn-dark');
    const currentTimeLabel = document.getElementById('current-time');
    const backToTopBtn = document.getElementById('back-to-top');
    const bottomToTopBtn = document.getElementById('bottom-to-top');
    let activeScrollTarget = window;

    function updateTopThemeLabel(resolvedTheme) {
        if (!currentTimeLabel) return;
        if (resolvedTheme === 'dark') {
            currentTimeLabel.innerHTML = '<i class="fa-solid fa-moon"></i> Tsukuyomi';
        } else {
            currentTimeLabel.innerHTML = '<i class="fa-solid fa-sun"></i> Amaterasu';
        }
    }

    function getUTC8Hour() {
        const d = new Date();
        const utc = d.getTime() + (d.getTimezoneOffset() * 60000);
        const utc8 = new Date(utc + (3600000 * 8));
        return utc8.getHours();
    }

    function isNightTimeInUTC8() {
        const hour = getUTC8Hour();
        return hour >= 18 || hour < 6;
    }

    function setTheme(theme) {
        let resolvedTheme = 'light';
        if (theme === 'auto') {
            const isNight = isNightTimeInUTC8();
            resolvedTheme = isNight ? 'dark' : 'light';
            document.documentElement.setAttribute('data-theme', resolvedTheme);
        } else {
            resolvedTheme = theme;
            document.documentElement.setAttribute('data-theme', theme);
        }
        try {
            localStorage.setItem('yuedu-theme', theme);
        } catch(e) {}
        updateTopThemeLabel(resolvedTheme);

        [themeAutoBtn, themeLightBtn, themeDarkBtn].forEach(btn => {
            if (btn) btn.classList.remove('active');
        });
        if (theme === 'auto' && themeAutoBtn) themeAutoBtn.classList.add('active');
        if (theme === 'light' && themeLightBtn) themeLightBtn.classList.add('active');
        if (theme === 'dark' && themeDarkBtn) themeDarkBtn.classList.add('active');
    }

    setInterval(() => {
        let stored = 'auto';
        try { stored = localStorage.getItem('yuedu-theme') || 'auto'; } catch(e) {}
        if (stored === 'auto') {
            const isNight = isNightTimeInUTC8();
            const currentTheme = document.documentElement.getAttribute('data-theme');
            const targetTheme = isNight ? 'dark' : 'light';
            if (currentTheme !== targetTheme) {
                document.documentElement.setAttribute('data-theme', targetTheme);
                updateTopThemeLabel(targetTheme);
            }
        }
    }, 60000); 

    if (themeAutoBtn) themeAutoBtn.addEventListener('click', () => setTheme('auto'));
    if (themeLightBtn) themeLightBtn.addEventListener('click', () => setTheme('light'));
    if (themeDarkBtn) themeDarkBtn.addEventListener('click', () => setTheme('dark'));

    let savedTheme = 'auto';
    try { savedTheme = localStorage.getItem('yuedu-theme') || 'auto'; } catch(e) {}
    setTheme(savedTheme);

    function findScrollParent(element) {
        let parent = element ? element.parentElement : null;
        while (parent) {
            const style = window.getComputedStyle(parent);
            const overflowY = style.overflowY;
            if ((overflowY === 'auto' || overflowY === 'scroll') && parent.scrollHeight > parent.clientHeight + 20) {
                return parent;
            }
            parent = parent.parentElement;
        }
        return window;
    }

    function getScrollMetrics(target) {
        if (target && target !== window) {
            return {
                top: target.scrollTop,
                max: target.scrollHeight - target.clientHeight
            };
        }
        const doc = document.scrollingElement || document.documentElement;
        return {
            top: window.pageYOffset || doc.scrollTop || 0,
            max: doc.scrollHeight - window.innerHeight
        };
    }

    function executeSmoothScrollTop() {
        if (cardContainer && typeof cardContainer.scrollIntoView === 'function') {
            cardContainer.scrollIntoView({ behavior: 'smooth', block: 'start' });
            return;
        }
        if (activeScrollTarget && activeScrollTarget !== window) {
            activeScrollTarget.scrollTo({ top: 0, behavior: 'smooth' });
            return;
        }
        window.scrollTo({ top: 0, behavior: 'smooth' });
    }

    function toggleBackToTopButton() {
        if (!backToTopBtn) return;
        const { top, max } = getScrollMetrics(activeScrollTarget);
        backToTopBtn.classList.toggle('show', max > 120 && top > 80);
    }

    if (backToTopBtn) {
        backToTopBtn.addEventListener('click', executeSmoothScrollTop);
    }

    if (bottomToTopBtn) {
        bottomToTopBtn.addEventListener('click', executeSmoothScrollTop);
    }

    const animatedContent = document.getElementById('animated-content');
    const highlightVars = ['var(--hl-1)', 'var(--hl-2)', 'var(--hl-3)'];

    const applyCode = (t) => t.replace(/`(.*?)`/g, (m, c) => `<code>${c}</code>`);
    const applyBold = (t) => t.replace(/\*\*(.*?)\*\*/g, (m, c) => `<strong>${c}</strong>`);
    const applyStrikethrough = (t) => t.replace(/\~\~(.*?)\~\~|<del>(.*?)<\/del>/g, (m, c1, c2) => `<s>${c1 || c2}</s>`);
    const applyItalic = (t) => t.replace(/\*(.*?)\*/g, (m, c) => `<em>${c}</em>`);
    const applyHighlight = (t) => t.replace(/(\[.*?\]|\(.*?\)|".*?"|“.*?”)/g, (m) => {
        const randomColor = highlightVars[Math.floor(Math.random() * highlightVars.length)];
        return `<span class="highlight" style="color: ${randomColor};">${m}</span>`;
    });

    function parseInlineMarkdown(text) {
        return applyHighlight(applyItalic(applyStrikethrough(applyBold(applyCode(text)))));
    }

    function parseContent(lines) {
        const htmlChunks = [];
        let i = 0;

        const isTableSeparator = (line) => /^\|(?:\s*:?-+:?\s*\|)+$/.test(line);

        while (i < lines.length) {
            const trimmedLine = lines[i].trim();

            if (i + 1 < lines.length && isTableSeparator(lines[i + 1].trim())) {
                const tableData = { headers: [], alignments: [], rows: [] };
                tableData.alignments = lines[i + 1].trim().split('|').slice(1, -1).map(s => {
                    const align = s.trim();
                    if (align.startsWith(':') && align.endsWith(':')) return 'center';
                    if (align.endsWith(':')) return 'right';
                    return 'left';
                });
                tableData.headers = lines[i].trim().split('|').slice(1, -1).map(s => s.trim());
                let rowIndex = i + 2;
                while (rowIndex < lines.length && lines[rowIndex].trim().startsWith('|')) {
                    tableData.rows.push(lines[rowIndex].trim().split('|').slice(1, -1).map(s => s.trim()));
                    rowIndex++;
                }
                let tableHTML = '<table><thead><tr>';
                tableData.headers.forEach((h, idx) => { tableHTML += `<th style="text-align: ${tableData.alignments[idx]};">${parseInlineMarkdown(h)}</th>`; });
                tableHTML += '</tr></thead><tbody>';
                tableData.rows.forEach(r => {
                    tableHTML += '<tr>';
                    r.forEach((c, idx) => { tableHTML += `<td style="text-align: ${tableData.alignments[idx]};">${parseInlineMarkdown(c)}</td>`; });
                    tableHTML += '</tr>';
                });
                tableHTML += '</tbody></table>';
                htmlChunks.push(tableHTML);
                i = rowIndex;

            } else if (trimmedLine.startsWith('>')) {
                const quoteGroup = [];
                let currentIndex = i;
                while (currentIndex < lines.length && lines[currentIndex].trim().startsWith('>')) {
                    quoteGroup.push(lines[currentIndex].trim());
                    currentIndex++;
                }
                const nestedLines = quoteGroup.map(line => line.substring(line.indexOf('>') + 1));
                const innerHtml = parseContent(nestedLines).join('');
                htmlChunks.push(`<div class="quote-center">${innerHtml}</div>`);
                i = currentIndex;

            } else if (trimmedLine.startsWith('||')) {
                const groupedRawInnerLines = [];
                let currentIndex = i;
                while (currentIndex < lines.length && lines[currentIndex].trim().startsWith('||')) {
                    const currentBlockLine = lines[currentIndex].trim();
                    let rawInnerLine = currentBlockLine.substring(2);
                    let cleanedInnerLine = rawInnerLine.replace(/\|\|/g, '');
                    groupedRawInnerLines.push(cleanedInnerLine);
                    currentIndex++;
                }
                const parsedInnerHtml = parseContent(groupedRawInnerLines).join('');
                htmlChunks.push(`<div class="highlight-block">${parsedInnerHtml}</div>`);
                i = currentIndex;

            } else if (trimmedLine.startsWith('* ')) {
                const listItems = [];
                let currentIndex = i;
                while (currentIndex < lines.length && lines[currentIndex].trim().startsWith('* ')) {
                    listItems.push(lines[currentIndex].trim().substring(2));
                    currentIndex++;
                }
                htmlChunks.push(`<ul>${listItems.map(item => `<li>${parseInlineMarkdown(item)}</li>`).join('')}</ul>`);
                i = currentIndex;

            } else if (/^---+\s*$/.test(trimmedLine)) {
                htmlChunks.push('<hr>');
                i++;

            } else {
                if (trimmedLine === '') {
                    if (htmlChunks.length === 0 || htmlChunks[htmlChunks.length - 1] !== '<div class="empty-line"></div>') {
                        htmlChunks.push('<div class="empty-line"></div>');
                    }
                } else {
                    const headingMatch = trimmedLine.match(/^(\#{1,4})\s(.*)/);
                    if (headingMatch) {
                        const level = headingMatch[1].length;
                        const content = headingMatch[2];
                        htmlChunks.push(`<h${level}>${parseInlineMarkdown(content)}</h${level}>`);
                    } else {
                        htmlChunks.push(`<div>${parseInlineMarkdown(trimmedLine)}</div>`);
                    }
                }
                i++;
            }
        }
        return htmlChunks;
    }

    let rawContent = '';
    const rawDataEl = document.getElementById('raw-data');
    const rawText = rawDataEl ? rawDataEl.textContent : '';
    const startEndMatch = rawText.match(/<start>([\s\S]*?)<end>/);
    rawContent = (startEndMatch && startEndMatch[1]) ? startEndMatch[1].trim() : rawText;

    const initialLines = rawContent.split('\n');
    const finalHtmlBlocks = parseContent(initialLines);

    if (animatedContent) {
        animatedContent.innerHTML = finalHtmlBlocks.join('');
    }

    activeScrollTarget = findScrollParent(animatedContent);
    activeScrollTarget.addEventListener('scroll', toggleBackToTopButton, { passive: true });
    window.addEventListener('scroll', toggleBackToTopButton, { passive: true });
    window.addEventListener('resize', toggleBackToTopButton);
    requestAnimationFrame(toggleBackToTopButton);
});
</script>
