  background: linear-gradient(135deg, rgba(38, 44, 60, 0.78), rgba(26, 30, 43, 0.72));
  border: 1px solid rgba(255, 255, 255, 0.22);
  box-shadow: 0 6px 16px rgba(0, 0, 0, 0.24);
